import React from 'react';
import './Projects.css';

const PROJECTS = [
  {
    title: 'ExploitXplorers',
    desc: 'Community-driven cybersecurity platform offering hands-on knowledge and awareness for students.',
    tags: ['MERN', 'Auth', 'Security'],
    bg: '#000000',
    light: false,
  },
  {
    title: 'Priscripto',
    desc: 'AI-driven healthcare appointment system optimizing patient-doctor scheduling and accessibility.',
    tags: ['Next.js', 'AI', 'MongoDB'],
    bg: '#f81927',
    light: false,
  },
  {
    title: 'Hospital Booking',
    desc: 'Full-cycle medical management system for seamless appointment handling and patient records.',
    tags: ['React', 'Node.js', 'Express'],
    bg: '#f3f4f6',
    light: true,
  },
  {
    title: 'Blog System',
    desc: 'Dynamic content management space for creators to publish, manage, and share technical insights.',
    tags: ['React', 'Tailwind', 'Appwrite'],
    bg: '#111827',
    light: false,
  },
];

export default function Projects() {
  const ProjectCard = ({ proj }) => (
    <div className="flex-none w-[320px] lg:w-[450px] bg-white border-2 border-black flex flex-col group hover:-translate-y-2 hover:-translate-x-2 hover:shadow-[12px_12px_0px_0px_rgba(0,0,0,1)] transition-all duration-300">
      {/* Thumbnail Area */}
      <div 
        className="aspect-[16/10] border-b-2 border-black flex items-center justify-center relative overflow-hidden" 
        style={{ backgroundColor: proj.bg }}
      >
        <span className={`font-display font-black text-2xl lg:text-3xl uppercase tracking-tighter transition-all duration-500 group-hover:scale-110 group-hover:tracking-widest ${proj.light ? 'text-black/10' : 'text-white/10'}`}>
          {proj.title}
        </span>
        {/* Hover Arrow overlay */}
        <div className="absolute bottom-4 right-4 bg-white border-2 border-black p-2 opacity-0 translate-y-4 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-300">
          <svg className="w-6 h-6 -rotate-45" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M14 5l7 7m0 0l-7 7m7-7H3" />
          </svg>
        </div>
      </div>

      {/* Content Area */}
      <div className="p-8 flex-1 flex flex-col">
        <h3 className="font-display text-2xl font-black uppercase tracking-tight">{proj.title}</h3>
        <p className="text-gray-600 mt-4 text-sm lg:text-base leading-relaxed line-clamp-2 font-medium">
          {proj.desc}
        </p>

        <div className="mt-auto pt-8 flex flex-wrap gap-2">
          {proj.tags.map((tag) => (
            <span key={tag} className="font-mono text-[10px] font-bold uppercase px-2 py-1 bg-primary-50 text-primary-900 border border-black shadow-[2px_2px_0px_0px_rgba(0,0,0,1)]">
              {tag}
            </span>
          ))}
        </div>
      </div>
    </div>
  );

  const ViewAllCard = () => (
    <a 
      href="https://krishsatasiya.netlify.app/" 
      target="_blank" 
      rel="noopener noreferrer"
      className="flex-none w-[320px] lg:w-[450px] bg-primary-500 border-2 border-black flex flex-col items-center justify-center p-12 text-center group hover:-translate-y-2 hover:-translate-x-2 hover:shadow-[12px_12px_0px_0px_rgba(0,0,0,1)] transition-all duration-300"
    >
      <div className="mb-8 p-4 bg-white border-2 border-black rounded-full group-hover:rotate-12 transition-transform">
        <svg className="w-12 h-12 text-black" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 8l4 4m0 0l-4 4m4-4H3" />
        </svg>
      </div>
      <h3 className="font-display text-4xl lg:text-5xl font-black text-white uppercase tracking-tighter leading-none">
        Explore<br />All Works
      </h3>
      <div className="mt-8 font-mono text-sm font-bold text-white uppercase tracking-widest border-b-2 border-white pb-1">
        15+ Projects Total
      </div>
    </a>
  );

  const scrollItems = (
    <>
      {PROJECTS.map((p, i) => <ProjectCard key={`p-${i}`} proj={p} />)}
      <ViewAllCard />
    </>
  );

  return (
    <section className="py-24 bg-white overflow-hidden" id="projects">
      <div className="container mb-16">
        <div className="flex flex-col lg:flex-row lg:items-end lg:justify-between gap-8">
          <div className="max-w-2xl">
            <span className="font-mono text-primary-500 font-bold uppercase tracking-widest">Portfolio</span>
            <h2 className="font-display text-5xl lg:text-7xl font-black uppercase tracking-tighter leading-none mt-4">
              Featured<br />Projects
            </h2>
          </div>
          <div className="lg:max-w-md text-right">
            <p className="text-gray-600 font-medium text-lg lg:text-xl leading-relaxed">
              Crafting scalable full-stack solutions with precision and performance in every pixel.
            </p>
          </div>
        </div>
      </div>

      <div className="border-y-2 border-black bg-gray-50/50">
        <div className="flex animate-scroll hover:[animation-play-state:paused] py-16">
          <div className="flex gap-12 pr-12">
            {scrollItems}
          </div>
          <div className="flex gap-12 pr-12">
            {scrollItems}
          </div>
        </div>
      </div>
    </section>
  );
}
